import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.yGqRar0R.js";const d=JSON.parse('{"title":"Contributing to SLS","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function i(s,e,l,u,h,g){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="contributing-to-sls" tabindex="-1">Contributing to SLS <a class="header-anchor" href="#contributing-to-sls" aria-label="Permalink to &quot;Contributing to SLS&quot;">​</a></h1><p>We appreciate your interest in contributing to SLS. This page outlines how to submit bug reports, feature suggestions, and code changes.</p><p class="contributing-note">See <a href="https://github.com/jessefaler/SLS/blob/main/CONTRIBUTING.md">CONTRIBUTING.md</a> for additional information.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><p>The easiest way to get started is to ask for help in our <a href="https://discord.gg/BrH8GtyGSh" target="_blank" rel="noreferrer">Discord server</a>.</p><h2 id="how-to-contribute" tabindex="-1">How to contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to contribute&quot;">​</a></h2><p>There are several ways you can contribute to SLS:</p><h3 id="reporting-bugs" tabindex="-1">Reporting bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting bugs&quot;">​</a></h3><p>If you run into a bug, search the <a href="https://github.com/jessefaler/SLS/issues" target="_blank" rel="noreferrer">issue tracker</a> for an existing report first.</p><p>If nothing matches, open a <a href="https://github.com/jessefaler/SLS/issues/new" target="_blank" rel="noreferrer">new issue</a>. Follow any template provided, and describe the problem clearly, including steps to reproduce when possible. Screenshots, logs, or small code snippets often make issues much easier to resolve.</p><h3 id="suggesting-features" tabindex="-1">Suggesting features <a class="header-anchor" href="#suggesting-features" aria-label="Permalink to &quot;Suggesting features&quot;">​</a></h3><p>If you have an idea for improving SLS, open an issue on the <a href="https://github.com/jessefaler/SLS/issues" target="_blank" rel="noreferrer">issue tracker</a>. Describe the feature in enough detail for others to understand the goal: what problem it solves, how it might work, and any tradeoffs or implementation angles you have in mind.</p><h3 id="contributing-code" tabindex="-1">Contributing code <a class="header-anchor" href="#contributing-code" aria-label="Permalink to &quot;Contributing code&quot;">​</a></h3><ol><li><strong>Fork and clone</strong> — Fork <a href="https://github.com/jessefaler/SLS" target="_blank" rel="noreferrer">SLS</a> on GitHub, then clone <strong>your fork</strong> locally so you can push branches to it.</li><li><strong>Branch</strong> — Create a branch for your work (for example <code>fix/…</code> or <code>feature/…</code>) instead of committing directly on <code>main</code>.</li><li><strong>Tooling</strong> — SLS is primarily <strong>Go</strong> and <strong>Java</strong>. Install a recent Go toolchain and JDK appropriate for the modules you are changing, and use the repo’s usual build or test commands before you open a PR.</li><li><strong>Submit</strong> — Push your branch to your fork and open a <strong>pull request</strong> against the upstream repository. Summarize what changed and why, and link related issues if any.</li></ol><p>Pull requests are reviewed in line with the project’s <a href="https://github.com/jessefaler/SLS/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> (including the <a href="https://github.com/jessefaler/SLS/blob/main/icla.txt" target="_blank" rel="noreferrer">Individual Contributor License Agreement</a> where applicable).</p>',15)])])}const b=t(n,[["render",i]]);export{d as __pageData,b as default};
